package com.cloudres.spend;

import android.app.*;
import android.os.Bundle;
import android.content.*;
import android.graphics.Color;
import android.graphics.Typeface;
import android.graphics.drawable.GradientDrawable;
import android.net.Uri;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.text.*;
import java.util.*;

public class MainActivity extends Activity {
    private final int ink=Color.rgb(34,43,35), muted=Color.rgb(112,120,111), green=Color.rgb(64,91,67), pale=Color.rgb(235,240,231), bg=Color.rgb(247,248,245), line=Color.rgb(228,231,224);
    private LinearLayout root, body, nav;
    private JSONArray entries;
    private String page="home";
    private static final int PICK_CSV=41;
    private final String[] categories={"餐饮","交通","购物","日用","娱乐","居住","医疗","其他"};
    @Override public void onCreate(Bundle b){super.onCreate(b); getWindow().setStatusBarColor(bg);getWindow().setNavigationBarColor(Color.WHITE);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR); load(); render();}
    private void load(){try{entries=new JSONArray(getSharedPreferences("spend",0).getString("entries","[]"));}catch(Exception e){entries=new JSONArray();}}
    private void save(){getSharedPreferences("spend",0).edit().putString("entries",entries.toString()).apply();}
    private String today(){return new SimpleDateFormat("yyyy-MM-dd",Locale.CHINA).format(new Date());}
    private String month(){return new SimpleDateFormat("yyyy-MM",Locale.CHINA).format(new Date());}
    private double amount(JSONObject o){return o.optDouble("amount",0);}
    private double sum(String datePrefix,String source){double s=0;for(int i=0;i<entries.length();i++){JSONObject o=entries.optJSONObject(i);if(o==null)continue;if(o.optString("date").startsWith(datePrefix)&&(source.equals("全部")||source.equals(o.optString("source"))))s+=amount(o);}return s;}
    private String money(double v){return String.format(Locale.CHINA,"%,.2f",v);}
    private int dp(float v){return (int)(v*getResources().getDisplayMetrics().density+.5f);}
    private TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(Typeface.DEFAULT,Typeface.BOLD);t.setIncludeFontPadding(false);return t;}
    private LinearLayout col(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);return l;}
    private LinearLayout row(){LinearLayout l=new LinearLayout(this);l.setOrientation(LinearLayout.HORIZONTAL);l.setGravity(Gravity.CENTER_VERTICAL);return l;}
    private LinearLayout.LayoutParams lp(int w,int h){return new LinearLayout.LayoutParams(w<0?w:dp(w),h<0?h:dp(h));}
    private void pad(View v,int a,int b,int c,int d){v.setPadding(dp(a),dp(b),dp(c),dp(d));}
    private GradientDrawable shape(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    private TextView button(String label,Runnable action,boolean primary){TextView t=text(label,14,primary?Color.WHITE:green,true);t.setGravity(Gravity.CENTER);pad(t,14,13,14,13);t.setBackground(shape(primary?green:pale,14));t.setOnClickListener(v->action.run());return t;}
    private void render(){root=col();root.setBackgroundColor(bg);setContentView(root);
        LinearLayout header=row();pad(header,22,18,22,14);TextView brand=text("日账",25,ink,true);header.addView(brand,new LinearLayout.LayoutParams(0,-2,1));TextView date=text(new SimpleDateFormat("M月d日 E",Locale.CHINA).format(new Date()),13,muted,false);header.addView(date);root.addView(header);
        ScrollView scroll=new ScrollView(this);body=col();pad(body,20,4,20,22);scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
        nav=row();nav.setBackgroundColor(Color.WHITE);nav.setElevation(dp(8));String[][] tabs={{"⌂","概览","home"},{"☷","账单","records"},{"＋","设置","settings"}};for(String[] tab:tabs){LinearLayout item=col();item.setGravity(Gravity.CENTER);pad(item,0,12,0,10);TextView ic=text(tab[0],19,page.equals(tab[2])?green:muted,true);ic.setGravity(Gravity.CENTER);TextView label=text(tab[1],11,page.equals(tab[2])?green:muted,page.equals(tab[2]));label.setGravity(Gravity.CENTER);item.addView(ic);LinearLayout.LayoutParams p=lp(-1,-2);p.weight=1;nav.addView(item,p);item.setOnClickListener(v->{page=tab[2];render();});}root.addView(nav);
        if(page.equals("home"))home();else if(page.equals("records"))records();else settings();}
    private void home(){body.addView(text("今日支出",14,muted,false));TextView total=text("¥ "+money(sum(today(),"全部")),36,ink,true);total.setPadding(0,dp(10),0,dp(6));body.addView(total);body.addView(text("只统计已录入的账单",12,muted,false));
        LinearLayout card=col();pad(card,16,16,16,16);card.setBackground(shape(pale,18));LinearLayout r=row();r.addView(text("本月累计",14,green,true),new LinearLayout.LayoutParams(0,-2,1));r.addView(text("预算 ¥ 3,500",12,muted,false));card.addView(r);TextView monthTotal=text("¥ "+money(sum(month(),"全部")),27,ink,true);monthTotal.setPadding(0,dp(12),0,dp(10));card.addView(monthTotal);View track=new View(this);track.setBackground(shape(Color.rgb(211,220,206),20));card.addView(track,lp(-1,6));View fill=new View(this);double ratio=Math.min(1,sum(month(),"全部")/3500.0);fill.setBackground(shape(green,20));FrameLayout bar=new FrameLayout(this);bar.addView(track,new FrameLayout.LayoutParams(-1,dp(6)));FrameLayout.LayoutParams fp=new FrameLayout.LayoutParams((int)(getResources().getDisplayMetrics().widthPixels*.78*ratio),dp(6));bar.addView(fill,fp);card.addView(bar,lp(-1,6));TextView used=text(String.format(Locale.CHINA,"预算已使用 %.0f%%",ratio*100),12,muted,false);used.setPadding(0,dp(9),0,0);card.addView(used);LinearLayout.LayoutParams cp=lp(-1,-2);cp.topMargin=dp(20);body.addView(card,cp);
        body.addView(section("支付渠道", "本月"));LinearLayout channels=row();channels.addView(channel("微信支付",sum(month(),"微信"),"●",Color.rgb(7,173,95)),new LinearLayout.LayoutParams(0,dp(92),1));View gap=new View(this);channels.addView(gap,lp(10,1));channels.addView(channel("支付宝",sum(month(),"支付宝"),"●",Color.rgb(22,126,229)),new LinearLayout.LayoutParams(0,dp(92),1));body.addView(channels);
        body.addView(section("最近支出","查看全部"));int shown=0;for(int i=entries.length()-1;i>=0&&shown<4;i--){JSONObject o=entries.optJSONObject(i);if(o!=null){expenseRow(o);shown++;}}if(shown==0){TextView empty=text("还没有账单，先记下第一笔吧。",14,muted,false);pad(empty,0,18,0,18);body.addView(empty);}
        TextView add=button("＋  记一笔",()->addDialog(),true);LinearLayout.LayoutParams ap=lp(-1,-2);ap.topMargin=dp(18);body.addView(add,ap);TextView imp=button("导入微信 / 支付宝账单 CSV",()->pickCsv(),false);LinearLayout.LayoutParams ip=lp(-1,-2);ip.topMargin=dp(9);body.addView(imp,ip);
    }
    private View channel(String title,double amount,String icon,int color){LinearLayout c=col();pad(c,13,14,8,12);c.setBackground(shape(Color.WHITE,14));c.addView(text(icon+"  "+title,12,color,true));TextView n=text("¥ "+money(amount),19,ink,true);n.setPadding(0,dp(12),0,0);c.addView(n);return c;}
    private TextView section(String title,String action){TextView t=text(title+"                                 "+action,15,ink,true);t.setPadding(0,dp(24),0,dp(12));body.addView(t);return t;}
    private void expenseRow(JSONObject o){LinearLayout r=row();pad(r,0,13,0,13);TextView icon=text("●",12,o.optString("source").equals("微信")?Color.rgb(7,173,95):Color.rgb(22,126,229),true);r.addView(icon,lp(22,-2));LinearLayout info=col();info.addView(text(o.optString("title","消费"),14,ink,true));TextView sub=text(o.optString("category","其他")+" · "+o.optString("date")+" · "+o.optString("source"),11,muted,false);sub.setPadding(0,dp(5),0,0);info.addView(sub);r.addView(info,new LinearLayout.LayoutParams(0,-2,1));r.addView(text("− ¥"+money(amount(o)),14,ink,true));View divider=new View(this);divider.setBackgroundColor(line);body.addView(r);body.addView(divider,lp(-1,1));r.setOnLongClickListener(v->{new AlertDialog.Builder(this).setMessage("删除这笔支出？").setNegativeButton("取消",null).setPositiveButton("删除",(d,w)->{remove(o);save();render();}).show();return true;});}
    private void remove(JSONObject target){JSONArray a=new JSONArray();for(int i=0;i<entries.length();i++){JSONObject o=entries.optJSONObject(i);if(o!=target)a.put(o);}entries=a;}
    private void records(){body.addView(text("所有账单",24,ink,true));body.addView(text("长按一条记录即可删除",12,muted,false));LinearLayout filters=row();for(String s:new String[]{"全部","微信","支付宝"}){TextView b=button(s,()->{showRecords(s);},false);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.setMargins(dp(3),dp(16),dp(3),dp(8));filters.addView(b,p);}body.addView(filters);showRecords("全部");TextView add=button("＋ 记一笔",()->addDialog(),true);LinearLayout.LayoutParams p=lp(-1,-2);p.topMargin=dp(16);body.addView(add,p);TextView imp=button("导入 CSV 账单",()->pickCsv(),false);p=lp(-1,-2);p.topMargin=dp(8);body.addView(imp,p);}
    private void showRecords(String source){body.removeViews(Math.min(3,body.getChildCount()),Math.max(0,body.getChildCount()-3));body.addView(text("合计 ¥ "+money(sum("",source.equals("全部")?"全部":source)),14,muted,true));for(int i=entries.length()-1;i>=0;i--){JSONObject o=entries.optJSONObject(i);if(o!=null&&(source.equals("全部")||source.equals(o.optString("source"))))expenseRow(o);}}
    private void settings(){body.addView(text("数据与设置",24,ink,true));body.addView(text("账单仅保存在这台设备上。",14,muted,false));body.addView(section("数据导入","CSV"));body.addView(text("从微信支付或支付宝导出的账单文件中选择 CSV。导入前请检查文件格式；首版使用通用列名识别，若官方账单列名不同，可能需要后续适配。",13,muted,false));TextView importBtn=button("选择账单 CSV",()->pickCsv(),true);LinearLayout.LayoutParams p=lp(-1,-2);p.topMargin=dp(14);body.addView(importBtn,p);TextView add=button("手动记账",()->addDialog(),false);p=lp(-1,-2);p.topMargin=dp(10);body.addView(add,p);TextView exp=button("导出本地备份 JSON",()->exportBackup(),false);p=lp(-1,-2);p.topMargin=dp(10);body.addView(exp,p);body.addView(section("关于日账","v1.0"));body.addView(text("轻量、离线、只关注每日花费。微信和支付宝没有在本应用中登录，也未接入个人账单授权 API。",13,muted,false));}
    private void addDialog(){LinearLayout form=col();pad(form,20,8,20,0);EditText title=new EditText(this);title.setSingleLine();title.setHint("消费内容，例如：午餐");form.addView(title);EditText amt=new EditText(this);amt.setSingleLine();amt.setInputType(8194);amt.setHint("金额（元）");form.addView(amt);EditText date=new EditText(this);date.setSingleLine();date.setText(today());date.setHint("日期 YYYY-MM-DD");form.addView(date);Spinner source=new Spinner(this);source.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"微信","支付宝","现金/其他"}));form.addView(source);Spinner cat=new Spinner(this);cat.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,categories));form.addView(cat);new AlertDialog.Builder(this).setTitle("记一笔").setView(form).setNegativeButton("取消",null).setPositiveButton("保存",(d,w)->{try{double a=Double.parseDouble(amt.getText().toString().trim());if(a<=0)throw new Exception();JSONObject o=new JSONObject();o.put("title",title.getText().toString().trim().isEmpty()?"日常消费":title.getText().toString().trim());o.put("amount",a);o.put("date",date.getText().toString().trim());o.put("source",source.getSelectedItem().toString());o.put("category",cat.getSelectedItem().toString());entries.put(o);save();page="home";render();}catch(Exception e){new AlertDialog.Builder(this).setMessage("金额格式不正确，请输入大于 0 的数字。").setPositiveButton("知道了",null).show();}}).show();}
    private void pickCsv(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,PICK_CSV);}
    @Override protected void onActivityResult(int req,int res,Intent data){super.onActivityResult(req,res,data);if(req!=PICK_CSV||res!=RESULT_OK||data==null)return;try(InputStream in=getContentResolver().openInputStream(data.getData());BufferedReader br=new BufferedReader(new InputStreamReader(in,"UTF-8"))){String header=br.readLine();if(header==null)throw new Exception("文件为空");String[] h=split(header);int ai=find(h,"金额","amount","实付","支出");int di=find(h,"日期","时间","date","交易时间");int ti=find(h,"商品","说明","备注","交易对方","title","商品说明");int si=find(h,"支付方式","来源","source","付款方式");int ci=find(h,"分类","category");if(ai<0)throw new Exception("未识别金额列。请使用包含“金额/amount”的 CSV 表头。");int count=0;String line;while((line=br.readLine())!=null){String[] v=split(line);if(ai>=v.length)continue;String av=v[ai].replace("¥","").replace("￥","").replace(",","").trim();if(av.isEmpty()||av.equals("--"))continue;double a;try{a=Math.abs(Double.parseDouble(av));}catch(Exception ex){continue;}if(a==0)continue;JSONObject o=new JSONObject();o.put("amount",a);o.put("title",value(v,ti,"消费"));o.put("date",normalizeDate(value(v,di,today())));String src=value(v,si,"");o.put("source",src.contains("微信")?"微信":src.contains("支付宝")?"支付宝":"其他");o.put("category",value(v,ci,"其他"));entries.put(o);count++;}save();render();new AlertDialog.Builder(this).setMessage("已导入 "+count+" 条记录。请核对日期、金额和收支方向。").setPositiveButton("完成",null).show();}catch(Exception e){new AlertDialog.Builder(this).setTitle("导入失败").setMessage(e.getMessage()==null?"无法读取该文件":e.getMessage()).setPositiveButton("确定",null).show();}}
    private String[] split(String s){return s.split(",(?=(?:[^\"]*\"[^\"]*\")*[^\"]*$)",-1);}
    private int find(String[] h,String... keys){for(int i=0;i<h.length;i++){String x=h[i].replace("\"","").trim().toLowerCase(Locale.ROOT);for(String k:keys)if(x.contains(k.toLowerCase(Locale.ROOT)))return i;}return -1;}
    private String value(String[] v,int i,String d){if(i<0||i>=v.length)return d;return v[i].replace("\"","").trim();}
    private String normalizeDate(String s){try{String x=s.trim().replace("/","-");if(x.length()>=10)return x.substring(0,10);return today();}catch(Exception e){return today();}}
    private void exportBackup(){try{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/json");i.putExtra(Intent.EXTRA_TITLE,"daily-spend-backup.json");startActivityForResult(i,42);}catch(Exception e){toast("暂不支持导出");}}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_SHORT).show();}
}
